SELECT *
FROM fabric_management
WHERE fb_type IN (
  SELECT fc_ct_name
  FROM fabric_category
  WHERE fc_ct_name = #{fc_ct_name}
);

mapper.update:
update customer_choice_option
set
    mp_id_pk = #{mp_id_pk},
    po_id_pk = #{po_id_pk}
where
    ct_id_pk = #{ct_id_pk}
    and oc_id_pk = #{oc_id_pk}

update customer_img
set ci_img_url = #{ci_img_url}
where
    ci_id_pk = #{ci_id_pk}
    and ct_id_pk = #{ct_id_pk}
